/**
 * Outcome of one ChangePoller scan. On a complete scan the checkpoint is the
 * max sys_updated_on seen (or the old checkpoint when nothing matched); on
 * any failure it is the caller's old checkpoint so no change is ever skipped.
 */
public final class PollResult {
    public final List<ChangeRecord> records;
    public final String checkpoint;
    public final boolean complete;
    public final String failure; // null on success; UNAUTHORIZED/FORBIDDEN/RATE_LIMITED/...

    public PollResult(List<ChangeRecord> records, String checkpoint,
                      boolean complete, String failure) {
        // Snapshot: later mutation of the caller's list must not show through.
        this.records = Collections.unmodifiableList(new ArrayList<>(records));
        this.checkpoint = checkpoint;
        this.complete = complete;
        this.failure = failure;
    }
}
