import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.IntConsumer;

/**
 * Polls change_request for approved changes updated strictly after a
 * checkpoint, paging with sysparm_limit/sysparm_offset until a short page.
 * Query, projection and retry policy are pinned in docs/contract.json.
 */
public final class ChangePoller {

    private static final String TABLE = "change_request";
    private static final List<String> FIELDS = List.of(
            "sys_id", "number", "short_description",
            "assignment_group", "approval", "sys_updated_on");
    private static final int MAX_RETRIES = 3;

    private final SnowTableClient client;
    private final int pageSize;
    private final IntConsumer sleeper;

    public ChangePoller(SnowTableClient client, int pageSize, IntConsumer sleeper) {
        // Termination and offset advancement require a strictly positive page
        // size: with pageSize <= 0 an empty page is never "short" and the
        // offset never moves.
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be > 0, got " + pageSize);
        }
        this.client = Objects.requireNonNull(client, "client");
        this.pageSize = pageSize;
        this.sleeper = Objects.requireNonNull(sleeper, "sleeper");
    }

    public PollResult poll(String checkpoint) throws IOException, InterruptedException {
        String query = "approval=approved^sys_updated_on>" + checkpoint
                + "^ORDERBYsys_updated_on";
        List<ChangeRecord> collected = new ArrayList<>();
        String maxSeen = checkpoint;
        int offset = 0;
        while (true) {
            SnowTableClient.Page page;
            try {
                page = fetchWithRetry(query, offset);
            } catch (SnowApiException e) {
                // Incomplete scan: keep what we have, never move the checkpoint.
                return new PollResult(collected, checkpoint, false, classify(e.statusCode));
            }
            for (Map<String, Object> raw : page.records) {
                ChangeRecord record = ChangeRecord.from(raw);
                collected.add(record);
                if (record.sysUpdatedOn.compareTo(maxSeen) > 0) {
                    maxSeen = record.sysUpdatedOn;
                }
            }
            if (page.records.size() < pageSize) {
                break;
            }
            offset += pageSize;
        }
        return new PollResult(collected, maxSeen, true, null);
    }

    /** Fetches one page, retrying a 429 at most MAX_RETRIES times. */
    private SnowTableClient.Page fetchWithRetry(String query, int offset)
            throws SnowApiException, IOException, InterruptedException {
        int retries = 0;
        while (true) {
            try {
                return client.fetchPage(TABLE, query, FIELDS, pageSize, offset, false, true);
            } catch (SnowApiException e) {
                if (e.statusCode != 429 || retries >= MAX_RETRIES) {
                    throw e;
                }
                retries++;
                sleeper.accept(e.retryAfter);
            }
        }
    }

    private static String classify(int statusCode) {
        switch (statusCode) {
            case 401: return "UNAUTHORIZED";
            case 403: return "FORBIDDEN";
            case 429: return "RATE_LIMITED";
            default:  return "HTTP_" + statusCode;
        }
    }
}
